 function begin(value,selectAll=false){if(editing)return;editing=true;formulaEditing=false;editor.hidden=false;editor.style.opacity='1';editor.style.pointerEvents='auto';positionRect(editor,C.expanded(sheet(),C.rect(active)));const st=stAt(...active);Object.assign(editor.style,{fontFamily:st.font,fontSize:st.size+'pt',fontWeight:st.bold?'700':'400',fontStyle:st.italic?'italic':'normal',color:st.color,textAlign:st.align==='general'?'left':st.align,backgroundColor:st.fill==='none'?'#ffffff':st.fill});editor.value=value===undefined?C.raw(C.get(sheet(),...active)):value;editor.focus({preventScroll:true});if(selectAll)editor.select();else editor.setSelectionRange(editor.value.length,editor.value.length);fitEditor();say('編集　Enterで確定 / Escで取消');}
