   if(table.dataset.excelHtml){try{const data=JSON.parse(table.dataset.excelHtml);if(data.version!==1||!Number.isInteger(data.rows)||!Number.isInteger(data.cols)||data.rows<1||data.cols<1)throw Error('コピー形式');const test={schema:C.SCHEMA,id:'test',revision:'test',title:'test',activeSheet:'s',sheets:[{id:'s',name:'test',rows:data.rows,cols:data.cols,cells:data.cells,merges:data.merges,colWidths:data.colWidths||[],rowHeights:data.rowHeights||[]}]};C.validate(test);return data;}catch(e){throw Error('コピー元の編集データが不正です: '+e.message);}}
   const rules=[];doc.querySelectorAll('style').forEach(s=>rules.push(...C.parseRules(s.textContent)));
